 "content": "def transform(grid):
    """Fill one-cell horizontal gaps between equal non-background markers with 2."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        for c in range(len(row) - 2):
            if row[c] != background and row[c] == row[c + 2] and row[c + 1] == background:
                out[r][c + 1] = 2
    return out
